export const ORDER_TERMINAL_STATES = ["CLOSED", "CANCELLED", "REJECTED"];
export const ORDER_SELF_LOOP_ACTIONS = [
    "report_production_progress",
    "post_clarification",
    "upload_document",
    "add_observer",
    "remove_observer",
];
export function isOrderTerminal(state) {
    return ORDER_TERMINAL_STATES.includes(state);
}
export function isOrderActive(state) {
    return ORDER_ACTIVE_STATES.includes(state);
}
export function findOrderTransition(from, action, actorRole) {
    const matches = ORDER_TRANSITIONS.filter((t) => {
        if (t.action !== action)
            return false;
        if (t.from === "ANY_ACTIVE")
            return isOrderActive(from);
        if (t.from === "*") {
            return action === "add_observer" || action === "remove_observer";
        }
        return t.from === from;
    });
    if (actorRole) {
        const roleMatch = matches.find((t) => t.allowedRoles.includes(actorRole));
        if (roleMatch)
            return roleMatch;
    }
    return matches[0];
}
/** Self-loop and observer transitions keep current state. */
export function resolveOrderTargetState(from, transition) {
    if (transition.action === "post_clarification" ||
        transition.action === "upload_document" ||
        transition.action === "add_observer" ||
        transition.action === "remove_observer") {
        return from;
    }
    return transition.to;
}
